POPULAR = [
    "SPY","QQQ","IWM","NVDA","AMD","AAPL","TSLA","MSFT","META","AMZN",
    "GOOGL","NFLX","AVGO","INTC","MU","PLTR","SMCI","SMH","SOXL","COIN",
    "BTC-USD","ETH-USD","SOL-USD","DOGE-USD","XRP-USD","BNB-USD"
]
CRYPTO_NAMES = {
    "BTC-USD":"Bitcoin","ETH-USD":"Ethereum","SOL-USD":"Solana",
    "DOGE-USD":"Dogecoin","XRP-USD":"XRP","BNB-USD":"BNB"
}
CRYPTO_ALIASES = {
    "BTC":"BTC-USD","BITCOIN":"BTC-USD","ETH":"ETH-USD","ETHEREUM":"ETH-USD",
    "SOL":"SOL-USD","SOLANA":"SOL-USD","DOGE":"DOGE-USD","DOGECOIN":"DOGE-USD",
    "XRP":"XRP-USD","BNB":"BNB-USD"
}

def normalize_symbol(value):
    value = (value or "").strip().upper().replace(" ", "")
    return CRYPTO_ALIASES.get(value, value)

def esc(v):
    return html_lib.escape(str(v), quote=True)

def fmt_money(x):
    if pd.isna(x): return "N/A"
    return f"${x:,.2f}"

def fmt_large(x):
    if pd.isna(x): return "N/A"
    x=float(x)
    if abs(x)>=1e9: return f"${x/1e9:,.2f}B"
    if abs(x)>=1e6: return f"${x/1e6:,.2f}M"
    if abs(x)>=1e3: return f"${x/1e3:,.1f}K"
    return f"${x:,.0f}"

def is_crypto(symbol):
    return symbol.endswith("-USD")

def age_text(hours):
    if hours < 1: return f"{max(1,int(hours*60))}m ago"
    if hours < 24: return f"{hours:.1f}h ago"
    return f"{hours/24:.1f}d ago"

