# NEWS ENGINE
# ============================================================
HIGH_IMPACT = [
    "fed","fomc","interest rate","rate decision","cpi","inflation","ppi","nfp",
    "nonfarm","jobs report","payroll","gdp","powell","sec","regulation","approval",
    "etf","lawsuit","ban","hack","earnings","guidance","revenue","forecast",
    "downgrade","upgrade","acquisition","merger","bankruptcy","default","tariff",
    "sanctions","investigation","war","geopolitical","missile","strike"
]
MEDIUM_IMPACT = [
    "launch","partnership","product","analyst","outlook","production","supply",
    "demand","investor","funding","buyback","dividend","target","contract"
]

def news_impact(title):
    t=(title or "").lower()
    if any(k in t for k in HIGH_IMPACT): return "HIGH","high"
    if any(k in t for k in MEDIUM_IMPACT): return "MEDIUM","medium"
    return "NORMAL","normal"

def make_news_item(title,publisher,link,ts):
    now=time.time()
    try:
        ts=float(ts)
    except Exception:
        ts=now
    # reject obviously future timestamps
    if ts>now+3600: ts=now
    age=max(0,(now-ts)/3600)
    impact,cls=news_impact(title)
    return {
        "title":str(title).strip(),
        "publisher":str(publisher or "Market News").strip(),
        "link":link or "#",
        "age":age,
        "impact":impact,
        "cls":cls,
        "ts":ts
    }

@st.cache_data(ttl=300,show_spinner=False)
def yahoo_search_news(symbol):
    try:
        q=symbol.replace("-USD","")
        url=f"https://query1.finance.yahoo.com/v1/finance/search?q={quote_plus(q)}&newsCount=20&quotesCount=0"
        r=requests.get(url,headers={"User-Agent":"Mozilla/5.0"},timeout=12)
        if r.status_code!=200: return []
        data=r.json()
        out=[]
        for x in data.get("news",[]):
            title=x.get("title")
            if not title: continue
            ts=x.get("providerPublishTime")
            link=x.get("link") or (x.get("clickThroughUrl") or {}).get("url")
            pub=x.get("publisher") or "Yahoo Finance"
            out.append(make_news_item(title,pub,link,ts))
        return out
    except Exception:
        return []

@st.cache_data(ttl=300,show_spinner=False)
def google_news_rss(symbol):
    try:
        base=symbol.replace("-USD","")
        name=CRYPTO_NAMES.get(symbol,"")
        query=f"{base} {name} market news" if name else f"{base} stock market news"
        url=f"https://news.google.com/rss/search?q={quote_plus(query)}&hl=en-US&gl=US&ceid=US:en"
        r=requests.get(url,headers={"User-Agent":"Mozilla/5.0"},timeout=12)
        if r.status_code!=200: return []
        root=ET.fromstring(r.content)
        out=[]
        for item in root.findall(".//item"):
            title=item.findtext("title") or ""
            link=item.findtext("link") or "#"
            pub=item.findtext("source") or "Google News"
            pubdate=item.findtext("pubDate")
            try: ts=pd.Timestamp(pubdate).timestamp()
            except Exception: ts=time.time()
            out.append(make_news_item(title,pub,link,ts))
        return out
    except Exception:
        return []

@st.cache_data(ttl=300,show_spinner=False)
def yfinance_news(symbol):
    try:
        items=yf.Ticker(symbol).news or []
    except Exception:
        return []
    out=[]
    for item in items:
        if not isinstance(item,dict): continue
        content=item.get("content",item)
        title=content.get("title") or item.get("title")
        if not title: continue
        ts=content.get("providerPublishTime") or item.get("providerPublishTime")
        if not ts:
            pub=content.get("pubDate") or item.get("pubDate")
            try: ts=pd.Timestamp(pub).timestamp() if pub else time.time()
            except Exception: ts=time.time()
        provider=content.get("provider",{})
        publisher=provider.get("displayName") if isinstance(provider,dict) else None
        publisher=publisher or item.get("publisher") or "Market News"
        cu=content.get("canonicalUrl")
        ct=content.get("clickThroughUrl")
        link=cu.get("url") if isinstance(cu,dict) else None
        link=link or (ct.get("url") if isinstance(ct,dict) else None) or item.get("link") or "#"
        out.append(make_news_item(title,publisher,link,ts))
    return out

@st.cache_data(ttl=300,show_spinner=False)
def load_symbol_news(symbol):
    all_items=yahoo_search_news(symbol)+google_news_rss(symbol)+yfinance_news(symbol)
    now=time.time()
    cleaned=[]
    seen=set()
    for n in all_items:
        if n["age"]>24: continue
        key=re.sub(r"[^a-z0-9]+","",n["title"].lower())[:140]
        if key in seen: continue
        seen.add(key)
        cleaned.append(n)
    cleaned.sort(key=lambda x:(0 if x["impact"]=="HIGH" else 1 if x["impact"]=="MEDIUM" else 2,x["age"]))
    return cleaned[:10]

def news_html(items, title):
    head=f"""
    <div class="news-rail-head">
      <div><div class="news-rail-title">{esc(title)} NEWS</div>
      <div class="news-rail-sub">Major symbol-linked headlines · last 24 hours</div></div>
      <div class="news-live">LIVE</div>
    </div>"""
    if not items:
        return '<div class="news-rail">'+head+'<div class="news-empty">No fresh symbol-linked headlines were returned. Try refresh or another symbol.</div></div>'
    cards=[]
    for n in items:
        cards.append(f"""
        <div class="news-card">
          <div class="news-meta">
            <span class="badge {n['cls']}">{n['impact']}</span>
            <span>{esc(n['publisher'])}</span><span>·</span><span>{age_text(n['age'])}</span>
          </div>
          <a class="news-title" href="{esc(n['link'])}" target="_blank" rel="noopener">{esc(n['title'])}</a>
        </div>""")
    return '<div class="news-rail">'+head+''.join(cards)+'<div class="news-more">CLICK A HEADLINE TO OPEN SOURCE</div></div>'

