with main_col:
    # ========================================================
    # HERO
    # ========================================================
    st.markdown("""
    <div class="hero">
      <span class="live">LIVE MARKET INTELLIGENCE</span>
      <h1>T.W.S GAMMA TERMINAL</h1>
      <p>OPTIONS FLOW · GAMMA EXPOSURE · CALL WALL · PUT WALL · GAMMA FLIP · MAX PAIN · IV · MARKET NEWS</p>
    </div>
    """,unsafe_allow_html=True)

    # ========================================================
    # DATA LOADING
    # ========================================================
    def bs_gamma(S,K,T,sigma,r=0.0):
        S=np.asarray(S,dtype=float)
        with np.errstate(all="ignore"):
            d1=(np.log(S/K)+(r+0.5*sigma**2)*T)/(sigma*np.sqrt(T))
            g=np.exp(-0.5*d1**2)/np.sqrt(2*np.pi)/(S*sigma*np.sqrt(T))
        return np.nan_to_num(g,nan=0.0,posinf=0.0,neginf=0.0)

    def total_gex_at(S,K,T,iv,oi,sign):
        g=bs_gamma(S,K,T,iv)
        return float(np.sum(g*oi*100*S*S*.01*sign))

    def max_pain(chain):
        calls=chain[chain["side"]=="CALL"]
        puts=chain[chain["side"]=="PUT"]
        strikes=np.sort(chain["strike"].dropna().unique())
        if len(strikes)==0: return np.nan
        ck,co=calls["strike"].values,calls["openInterest"].values
        pk,po=puts["strike"].values,puts["openInterest"].values
        pain=[np.sum(np.maximum(p-ck,0)*co)+np.sum(np.maximum(pk-p,0)*po) for p in strikes]
        return float(strikes[int(np.argmin(pain))])

    def _clean(df):
        for c in ["openInterest","volume","impliedVolatility","strike"]:
            df[c]=pd.to_numeric(df[c],errors="coerce")
        df["openInterest"]=df["openInterest"].fillna(0.0)
        df["volume"]=df["volume"].fillna(0.0)
        df["impliedVolatility"]=df["impliedVolatility"].fillna(0.0)
        return df.dropna(subset=["strike"])

    def load_yahoo(symbol,n_exp):
        stock=yf.Ticker(symbol)
        spot=None
        try: spot=float(stock.fast_info["lastPrice"])
        except Exception: pass
        if not spot or np.isnan(spot):
            hist=stock.history(period="5d",auto_adjust=False)
            if hist.empty: raise ValueError("Yahoo: no price")
            spot=float(hist["Close"].iloc[-1])
        expirations=list(stock.options)
        if not expirations: raise ValueError("Yahoo: no options")
        rows=[]
        for exp in expirations[:n_exp]:
            try:
                oc=stock.option_chain(exp)
            except Exception:
                continue
            c,p=oc.calls.copy(),oc.puts.copy()
            c["side"]="CALL";p["side"]="PUT"
            c["expiration"]=exp;p["expiration"]=exp
            rows.extend([c,p])
        if not rows: raise ValueError("Yahoo: option chain empty")
        return spot,_clean(pd.concat(rows,ignore_index=True))

    def load_cboe(symbol,n_exp):
        headers={"User-Agent":"Mozilla/5.0"}
        data=None
        for sym in (symbol,"_"+symbol):
            try:
                r=requests.get(f"https://cdn.cboe.com/api/global/delayed_quotes/options/{sym}.json",headers=headers,timeout=18)
                if r.status_code==200:
                    data=r.json().get("data")
                    if data and data.get("options"): break
            except Exception: continue
        if not data or not data.get("options"): raise ValueError("Cboe: no data")
        spot=float(data.get("current_price") or data.get("close") or data.get("prev_day_close"))
        pat=re.compile(r"^(.*?)(\d{6})([CP])(\d{8})$")
        rows=[]
        for o in data["options"]:
            m=pat.match(str(o.get("option","")))
            if not m: continue
            _,date,cp,strike=m.groups()
            rows.append({
                "strike":int(strike)/1000.0,
                "side":"CALL" if cp=="C" else "PUT",
                "expiration":datetime.strptime(date,"%y%m%d").strftime("%Y-%m-%d"),
                "openInterest":o.get("open_interest"),
                "volume":o.get("volume"),
                "impliedVolatility":o.get("iv")
            })
        if not rows: raise ValueError("Cboe: parse failed")
        df=pd.DataFrame(rows)
        today=pd.Timestamp.today().normalize()
        df=df[pd.to_datetime(df["expiration"])>=today]
        keep=sorted(df["expiration"].unique())[:n_exp]
        return spot,_clean(df[df["expiration"].isin(keep)].reset_index(drop=True))

    @st.cache_data(ttl=120,show_spinner=False)
    def load_options(symbol,n_exp):
        errors=[]
        for _ in range(2):
            try:
                spot,df=load_yahoo(symbol,n_exp)
                return spot,df,"Yahoo Finance"
            except Exception as e:
                errors.append(str(e));time.sleep(.7)
        try:
            spot,df=load_cboe(symbol,n_exp)
            return spot,df,"Cboe delayed"
        except Exception as e:
            errors.append(str(e))
        raise ValueError("No options data: "+" | ".join(dict.fromkeys(errors)))

    def load_quote(symbol):
        t=yf.Ticker(symbol)
        price=None;change=None;volume=None
        try: price=float(t.fast_info["lastPrice"])
        except Exception: pass
        hist=t.history(period="5d",auto_adjust=False)
        if price is None and not hist.empty: price=float(hist["Close"].iloc[-1])
        if not hist.empty:
            prev=float(hist["Close"].iloc[-2]) if len(hist)>1 else float(hist["Close"].iloc[-1])
            if price and prev: change=(price/prev-1)*100
            volume=float(hist["Volume"].iloc[-1]) if "Volume" in hist else None
        return price,change,volume

    # Try options first; if crypto/no-options, use spot mode.
    options_mode=True
    try:
        spot,opt,source=load_options(ticker,n_exp)
    except Exception:
        options_mode=False
        try:
            spot,change,volume=load_quote(ticker)
        except Exception as e:
            st.error(f"Unable to load {ticker}: {e}")
            st.stop()
        if spot is None:
            st.error(f"No market price available for {ticker}.")
            st.stop()

    # ========================================================
    # SPOT / QUOTE HEADER
    # ========================================================
    if options_mode:
        st.markdown(
            f"<div style='margin:4px 0 8px;font-size:20px;font-weight:900'>{esc(ticker)} "
            f"<span style='font-size:10px;color:#61787f;font-weight:500'>Spot {fmt_money(spot)} · {esc(source)} · {datetime.now():%H:%M:%S}</span></div>",
            unsafe_allow_html=True
        )
    else:
        cname=CRYPTO_NAMES.get(ticker,ticker)
        chg=change or 0
        cls="pos" if chg>=0 else "neg"
        st.markdown(f"""
        <div class="quote-card">
          <div class="quote-symbol">{esc(cname)} · {esc(ticker)}</div>
          <div class="quote-price">{fmt_money(spot)}</div>
          <div class="quote-change {cls}">{chg:+.2f}% · LIVE SPOT QUOTE</div>
          <div class="quote-grid">
            <div class="quote-stat"><span>24H / Recent High</span><b>Market feed</b></div>
            <div class="quote-stat"><span>Volume</span><b>{fmt_large(volume) if volume else "N/A"}</b></div>
            <div class="quote-stat"><span>News</span><b>{len(news_items)} headlines</b></div>
            <div class="quote-stat"><span>Options</span><b>Not listed</b></div>
          </div>
        </div>
        """,unsafe_allow_html=True)
        st.info("Options-chain analytics are unavailable for this symbol, so T.W.S shows live spot + news mode instead.")

    # ========================================================
    # OPTIONS ANALYTICS
    # ========================================================
    if options_mode:
        exp_ts=pd.to_datetime(opt["expiration"])+pd.Timedelta(hours=20)
        days=(exp_ts-pd.Timestamp.utcnow().tz_localize(None)).dt.total_seconds()/86400
        opt["T"]=np.maximum(days.values,.5)/365
        opt["sign"]=np.where(opt["side"]=="CALL",1.0,-1.0)

        valid=(opt["impliedVolatility"]>.01)&(opt["impliedVolatility"]<5)&(opt["openInterest"]>0)
        g_opt=opt[valid].copy()
        K=g_opt["strike"].values.astype(float)
        T=g_opt["T"].values
        IV=g_opt["impliedVolatility"].values
        OI=g_opt["openInterest"].values
        SG=g_opt["sign"].values
        g_opt["GEX"]=bs_gamma(spot,K,T,IV)*OI*100*spot*spot*.01*SG
        net_gex=float(g_opt["GEX"].sum())

        calls=opt[opt["side"]=="CALL"];puts=opt[opt["side"]=="PUT"]
        c_oi=calls.groupby("strike")["openInterest"].sum()
        p_oi=puts.groupby("strike")["openInterest"].sum()
        c_above=c_oi[c_oi.index>=spot];p_below=p_oi[p_oi.index<=spot]
        call_wall=float((c_above if not c_above.empty else c_oi).idxmax())
        put_wall=float((p_below if not p_below.empty else p_oi).idxmax())

        grid=np.linspace(spot*.8,spot*1.2,161)
        profile=np.array([total_gex_at(s,K,T,IV,OI,SG) for s in grid])
        gamma_flip=np.nan
        cross=np.where(np.sign(profile[:-1])*np.sign(profile[1:])<0)[0]
        if len(cross):
            best=min(cross,key=lambda i:abs(grid[i]-spot))
            x0,x1,y0,y1=grid[best],grid[best+1],profile[best],profile[best+1]
            if y1!=y0: gamma_flip=float(x0-y0*(x1-x0)/(y1-y0))

        mp_rows=[]
        for exp,ch in opt.groupby("expiration",sort=True):
            near=ch.iloc[(ch["strike"]-spot).abs().argsort()[:6]]
            atm=near.loc[near["impliedVolatility"]>.01,"impliedVolatility"].mean()*100
            pc=ch.loc[ch.side=="PUT","openInterest"].sum()/max(ch.loc[ch.side=="CALL","openInterest"].sum(),1)
            mp_rows.append({
                "Expiration":exp,
                "DTE":round(ch["T"].iloc[0]*365,1),
                "Max Pain":max_pain(ch),
                "ATM IV %":round(atm,2) if pd.notna(atm) else np.nan,
                "Put/Call OI":round(pc,2),
                "Total OI":int(ch["openInterest"].sum()),
                "Volume":int(ch["volume"].sum())
            })
        exp_table=pd.DataFrame(mp_rows)
        valid_mp=exp_table.dropna(subset=["Max Pain"])
        mp_main=float(valid_mp["Max Pain"].iloc[0]) if not valid_mp.empty else np.nan
        atm_main=exp_table["ATM IV %"].dropna()
        atm_iv=float(atm_main.iloc[0]) if not atm_main.empty else np.nan
        levels=[x for x in [call_wall,put_wall,gamma_flip,mp_main] if pd.notna(x)]
        magnetic=min(levels,key=lambda x:abs(x-spot)) if levels else np.nan

        # Metrics
        metrics=[
            ("SPOT PRICE",fmt_money(spot),"Underlying"),
            ("CALL WALL",fmt_money(call_wall),"Highest call OI above"),
            ("PUT WALL",fmt_money(put_wall),"Highest put OI below"),
            ("GAMMA FLIP",fmt_money(gamma_flip),"GEX crosses zero"),
            ("MAX PAIN",fmt_money(mp_main),f"Nearest exp {valid_mp['Expiration'].iloc[0]}" if not valid_mp.empty else ""),
            ("ATM IV",f"{atm_iv:.2f}%" if pd.notna(atm_iv) else "N/A","Nearest expiration")
        ]
        cols=st.columns(6)
        for c,(lab,val,sub) in zip(cols,metrics):
            c.markdown(f'<div class="metric-card"><div class="metric-label">{lab}</div><div class="metric-value">{val}</div><div class="metric-sub">{sub}</div></div>',unsafe_allow_html=True)

        st.markdown('<div class="section-title">KEY MARKET STRUCTURE</div>',unsafe_allow_html=True)
        call_dist=(call_wall/spot-1)*100
        put_dist=(put_wall/spot-1)*100
        regime="Positive Gamma · dampening" if net_gex>0 else "Negative Gamma · amplifying"
        rg_cls="pos" if net_gex>0 else "neg"
        c1,c2,c3,c4=st.columns(4)
        c1.markdown(f'<div class="level-card level-pain"><div class="level-name">Magnetic Level</div><div class="level-price">{fmt_money(magnetic)}</div></div>',unsafe_allow_html=True)
        c2.markdown(f'<div class="level-card level-call"><div class="level-name">Call Wall Distance</div><div class="level-price pos">{call_dist:+.2f}%</div></div>',unsafe_allow_html=True)
        c3.markdown(f'<div class="level-card level-put"><div class="level-name">Put Wall Distance</div><div class="level-price neg">{put_dist:+.2f}%</div></div>',unsafe_allow_html=True)
        c4.markdown(f'<div class="level-card level-flip"><div class="level-name">Net GEX / 1% MOVE</div><div class="level-price {rg_cls}">{fmt_large(net_gex)}</div><div class="metric-sub">{regime}</div></div>',unsafe_allow_html=True)

        lo,hi=spot*(1-window/100),spot*(1+window/100)
        chart_h=320

        def rule(x,color,label):
            if pd.isna(x):
                return alt.Chart(pd.DataFrame({"x":[],"l":[]})).mark_rule()
            d=pd.DataFrame({"x":[x],"l":[label]})
            r=alt.Chart(d).mark_rule(color=color,strokeDash=[5,4],size=2).encode(x="x:Q")
            t=alt.Chart(d).mark_text(color=color,align="left",dx=4,dy=-8,fontSize=9).encode(x="x:Q",text="l:N")
            return r+t

        st.markdown('<div class="section-title">GAMMA EXPOSURE · GEX BY STRIKE</div>',unsafe_allow_html=True)
        gs=g_opt.groupby("strike")["GEX"].sum().reset_index()
        gs=gs[(gs.strike>=lo)&(gs.strike<=hi)]
        gs["GEX_M"]=gs["GEX"]/1e6
        gs["dir"]=np.where(gs["GEX_M"]>=0,"Positive","Negative")
        bars=alt.Chart(gs).mark_bar().encode(
            x=alt.X("strike:Q",title="Strike",scale=alt.Scale(domain=[lo,hi])),
            y=alt.Y("GEX_M:Q",title="GEX ($M / 1%)"),
            color=alt.Color("dir:N",scale=alt.Scale(domain=["Positive","Negative"],range=["#5cff9d","#ff5872"]),legend=None),
            tooltip=["strike",alt.Tooltip("GEX_M:Q",format=",.1f")]
        )
        st.altair_chart((bars+rule(spot,"#ffffff","Spot")+rule(gamma_flip,"#e6bd58","Flip")+rule(call_wall,"#5cff9d","Call Wall")+rule(put_wall,"#ff5872","Put Wall")).properties(height=chart_h),use_container_width=True)

        left,right=st.columns(2)
        with left:
            st.markdown('<div class="section-title">OPEN INTEREST BY STRIKE</div>',unsafe_allow_html=True)
            oi_df=opt.groupby(["strike","side"])["openInterest"].sum().reset_index()
            oi_df=oi_df[(oi_df.strike>=lo)&(oi_df.strike<=hi)]
            oc=alt.Chart(oi_df).mark_bar(opacity=.9).encode(
                x=alt.X("strike:Q",title="Strike",scale=alt.Scale(domain=[lo,hi])),
                y=alt.Y("openInterest:Q",title="Open Interest",stack=None),
                color=alt.Color("side:N",scale=alt.Scale(domain=["CALL","PUT"],range=["#5cff9d","#ff5872"]),legend=alt.Legend(orient="top",title=None)),
                tooltip=["strike","side",alt.Tooltip("openInterest:Q",format=",")]
            )
            st.altair_chart((oc+rule(spot,"#ffffff","Spot")).properties(height=chart_h),use_container_width=True)

        with right:
            st.markdown('<div class="section-title">GEX PROFILE VS SPOT</div>',unsafe_allow_html=True)
            prof=pd.DataFrame({"price":grid,"GEX_M":profile/1e6})
            line=alt.Chart(prof).mark_line(color="#5cff9d",size=3).encode(
                x=alt.X("price:Q",title="Hypothetical spot",scale=alt.Scale(zero=False)),
                y=alt.Y("GEX_M:Q",title="Total GEX ($M)")
            )
            zero=alt.Chart(pd.DataFrame({"y":[0]})).mark_rule(color="#42545a").encode(y="y:Q")
            st.altair_chart((line+zero+rule(spot,"#ffffff","Spot")+rule(gamma_flip,"#e6bd58","Flip")).properties(height=chart_h),use_container_width=True)

        st.markdown('<div class="section-title">EXPIRATION DATA</div>',unsafe_allow_html=True)
        st.dataframe(exp_table,use_container_width=True,hide_index=True)

        iv_plot=exp_table.dropna(subset=["ATM IV %"])
        if len(iv_plot)>1:
            st.markdown('<div class="section-title">IV TERM STRUCTURE</div>',unsafe_allow_html=True)
            ivc=alt.Chart(iv_plot).mark_line(point=True,color="#e6bd58",size=3).encode(
                x=alt.X("DTE:Q",title="Days to expiry"),
                y=alt.Y("ATM IV %:Q",scale=alt.Scale(zero=False)),
                tooltip=["Expiration","DTE","ATM IV %"]
            )
            st.altair_chart(ivc.properties(height=240),use_container_width=True)

        st.markdown('<div class="section-title">TOP 10 STRIKES BY OPEN INTEREST</div>',unsafe_allow_html=True)
        top=(opt.pivot_table(index="strike",columns="side",values="openInterest",aggfunc="sum",fill_value=0)
             .assign(Total=lambda d:d.sum(axis=1)).sort_values("Total",ascending=False).head(10).reset_index())
        st.dataframe(top,use_container_width=True,hide_index=True)

